331	   331	          // Fallback for a channel with no usable destination — either the field is absent
332	   332	          // for this storefront, or isSafeHref rejected the value. Both reach here, and both
333	   333	          // want the same treatment. NON-INTERACTIVE but PERCEIVABLE:
334	   334	          //   - <span>: no href, no tabIndex, so nothing promises an action that cannot be
335	   335	          //     performed (avoids the WCAG 2.4.4 / 3.2.4 false affordance).
336	   336	          //   - labelled, not aria-hidden: ZimmIcon emits role="img" + aria-label, so screen
337	   337	          //     reader users learn the channel exists instead of getting silence (avoids the
338	   338	          //     1.1.1 information loss the previous aria-hidden caused).
339	   339	          // Not dead code: contact channels are optional per storefront, so a locale that
340	   340	          // supplies only e.g. email still renders the other two icons this way.
341	   341	          <chakra.span key={icon} __css={styles.contactIconLink}>
342	   342	            <ZimmIcon type={icon} size="md" aria-label={label} />
343	   343	          </chakra.span>
344	   344	        ),
345	   345	      )}
346	   346	    </chakra.div>
347	   347	  );
348	   348	};
349	   349	
350	   350	// ---------------------------------------------------------------------------
351	   351	// Bottom bar
352	   352	// ---------------------------------------------------------------------------
353	   353	type BottomBarProps = {
354	   354	  copyrightYear: number;
355	   355	  copyrightOwner: string;
356	   356	  legalLinks: ReadonlyArray<{ label: string; href: string }>;
357	   357	};
358	   358	
