401	   401	};
402	   402	
403	   403	// ---------------------------------------------------------------------------
404	   404	// Footer
405	   405	// ---------------------------------------------------------------------------
406	   406	
407	   407	/**
408	   408	 * Zimmermann global footer — presentational. Receives its content as props and
409	   409	 * fetches nothing, matching every other Contentful-backed component in the repo
410	   410	 * (`DuplexSection`, `HeroBanner`, `ProductHero`, `VideoEmbed`).
411	   411	 *
412	   412	 * `data` is required by design: static content belongs in the story or in the
413	   413	 * container below, never baked into the component that renders production UI.
414	   414	 * Omneo email submit and Cookie Settings are separate stories (HPC-035, HPC-038).
415	   415	 */
416	   416	export const Footer = ({
417	   417	  data,
418	   418	  copyrightYear = new Date().getFullYear(),
419	   419	  initialSubscribed = false,
420	   420	  privacyPolicyHref = '#',
421	   421	  onLogoClick = noop,
422	   422	  enableNameCapture = false,
423	   423	}: FooterProps) => {
424	   424	  const {
425	   425	    subscribeHeading,
426	   426	    subscribeBody,
427	   427	    navGroups,
428	   428	    legalLinks = [],
429	   429	    copyrightOwner,
430	   430	    phoneHref,
431	   431	    whatsAppHref,
432	   432	    emailHref,
433	   433	  } = data.fields;
434	   434	
435	   435	  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
436	   436	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
437	   437	
438	   438	  return (
439	   439	    <chakra.footer role="contentinfo" __css={styles.container}>
440	   440	      <chakra.div __css={styles.main}>
441	   441	        <chakra.div __css={styles.contentRow}>
442	   442	          <chakra.div __css={styles.subscribe}>
443	   443	            <SubscribeSection
444	   444	              heading={subscribeHeading ?? ''}
445	   445	              body={subscribeBody ?? ''}
446	   446	              initialSubscribed={initialSubscribed}
447	   447	              privacyPolicyHref={privacyPolicyHref}
448	   448	              enableNameCapture={enableNameCapture}
449	   449	            />
450	   450	          </chakra.div>
451	   451	
452	   452	          <chakra.div __css={styles.links}>
453	   453	            <chakra.div __css={styles.linksInner}>
454	   454	              {navGroups.map((group) => (
455	   455	                <chakra.div key={group.sys.id} __css={styles.linkCol}>
456	   456	                  {/* Figma section column: flex-col gap-16px — the column gap replaces
457	   457	                                        marginBottom on the heading. Contact heading has 4px left offset. */}
458	   458	                  <chakra.p
459	   459	                    __css={{
460	   460	                      ...styles.columnHeading,
461	   461	                      ...(group.fields.showContactChannels ? { paddingLeft: '2xs' } : {}),
462	   462	                    }}
463	   463	                  >
464	   464	                    {group.fields.heading}
465	   465	                  </chakra.p>
466	   466	                  {/* Figma Links div (2228:19423): flex-col, items-start, width 100%, gap 0.
467	   467	                      DELIBERATE DEVIATION: Figma puts the Contact items at x=0 while indenting
468	   468	                      only its heading 4px (wrapper 40000407:22289) — About and Help headings sit
469	   469	                      flush at 0, so that asymmetry reads as a stray wrapper rather than intent.
470	   470	                      We indent the Contact items to match their heading so the column aligns as a
471	   471	                      unit. The icon row below needs no indent: its 24px box centres a 16px glyph,
472	   472	                      so the glyph edge already lands at 4px. Pending Kiera. */}
473	   473	                  <chakra.ul __css={styles.linkList}>
474	   474	                    {group.fields.links.map((link) => (
475	   475	                      <chakra.li
476	   476	                        key={link.sys.id}
477	   477	                        __css={{
478	   478	                          ...styles.linkListItem,
479	   479	                          ...(group.fields.showContactChannels ? { paddingLeft: '2xs' } : {}),
480	   480	                        }}
481	   481	                      >
482	   482	                        {/* Each item h-[24px] items-center, no gap. ZimmNavItem's baseStyle supplies
483	   483	                            minHeight 24px, whiteSpace normal (so the label below can wrap) and uppercase.
484	   484	
485	   485	                            width:min-content only for labels that carry a non-breaking space. A wrapped
486	   486	                            element takes the AVAILABLE width, not its longest line, so without this the
487	   487	                            Acknowledgement item filled linkCol's 160px cap while its longest line is
488	   488	                            115px — 45px of dead space that pushed the Contact column right, against
489	   489	                            Figma where every column hugs its content. min-content resolves to the widest
490	   490	                            unbreakable run, which the NBSP makes exactly "ACKNOWLEDGEMENT" (115px).
491	   491	                            It must stay gated: applied to a single-line label it collapses to the longest
492	   492	                            word and wraps it ("Book an Appointment" 131px -> 76px, two lines). */}
493	   493	                        <ZimmNavItem
494	   494	                          href={link.fields.href}
495	   495	                          label={link.fields.label}
496	   496	                          inverse
497	   497	                          sx={link.fields.label.includes(NBSP) ? { width: 'min-content' } : undefined}
498	   498	                        />
499	   499	                      </chakra.li>
500	   500	                    ))}
501	   501	                    {/* Contact channels are the LAST CHILD OF THE LIST, not a sibling of it —
502	   502	                        Figma's Icon-list (40002081:14616) sits inside Links at y=72, directly
503	   503	                        after "CONNECT WITH US" ends at y=72, so only its own 4px padding-top
504	   504	                        separates them. Rendered outside the <ul> it instead picked up linkCol's
505	   505	                        16px column gap and sat 20px low against Figma's 4px. */}
506	   506	                    {group.fields.showContactChannels && (
507	   507	                      <chakra.li __css={styles.linkListItem}>
508	   508	                        <ContactIconRow phoneHref={phoneHref} whatsAppHref={whatsAppHref} emailHref={emailHref} />
509	   509	                      </chakra.li>
510	   510	                    )}
511	   511	                  </chakra.ul>
512	   512	                </chakra.div>
513	   513	              ))}
514	   514	            </chakra.div>
515	   515	          </chakra.div>
516	   516	        </chakra.div>
517	   517	
518	   518	        <chakra.div __css={styles.logo}>
519	   519	          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
520	   520	              The handler comes from FooterContainer — see the note there on why it uses
521	   521	              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
522	   522	              reset only, so the logo keeps its own geometry. */}
523	   523	          <chakra.button type="button" aria-label="Zimmermann home" onClick={onLogoClick} __css={styles.logoButton}>
524	   524	            <ZimmLogo variant="inverse" />
525	   525	          </chakra.button>
526	   526	        </chakra.div>
527	   527	      </chakra.div>
528	   528	
529	   529	      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
530	   530	    </chakra.footer>
531	   531	  );
532	   532	};
533	   533	
534	   534	// ---------------------------------------------------------------------------
535	   535	// Container — the default export
536	   536	// ---------------------------------------------------------------------------
537	   537	
538	   538	/**
539	   539	 * The component SFCC actually renders. Base `_app/index.jsx` resolves
540	   540	 * `@salesforce/retail-react-app/app/components/footer` through the overrides system
541	   541	 * and renders `<Footer />` with **no props**, so there is no upstream container to
542	   542	 * own the data. This wrapper is that seam, and the only place static content lives.
543	   543	 *
544	   544	 * HPC-034: replace FOOTER_FIXTURE with the Contentful CDA fetch **here** — the
545	   545	 * presentational Footer above does not change. Note that puts a fetch inside
546	   546	 * `components/`, which components.md reserves for containers; if that matters,
547	   547	 * HPC-034 should override `_app` instead (Tier 2 shared shell — coordinate first).
548	   548	 */
549	   549	const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
550	   550	  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
551	   551	  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
552	   552	  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
553	   553	  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve
554	   554	  // home the same way on every storefront.
555	   555	  const { buildUrl } = useMultiSite();
556	   556	  const history = useHistory();
557	   557	  return <Footer data={FOOTER_FIXTURE} onLogoClick={() => history.push(buildUrl(HOME_HREF))} {...props} />;
558	   558	};
559	   559	
560	   560	export default FooterContainer;
